import{_ as e,c as i,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const l=JSON.parse('{"title":"Introduktion til mentalt spil - deltagervejledning","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/da/participant-guide.md","filePath":"public/downloads/da/participant-guide.md"}');const n=e({name:"public/downloads/da/participant-guide.md"},[["render",function(e,l,n,a,o,s){return r(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="introduktion-til-mentalt-spil-deltagervejledning" tabindex="-1">Introduktion til mentalt spil - deltagervejledning <a class="header-anchor" href="#introduktion-til-mentalt-spil-deltagervejledning" aria-label="Permalink to &quot;Introduktion til mentalt spil - deltagervejledning&quot;">​</a></h1><p><strong>Petanque Akademi</strong><em>Udvikling af elitespillere</em></p><hr><h2 id="velkomst" tabindex="-1">Velkomst <a class="header-anchor" href="#velkomst" aria-label="Permalink to &quot;Velkomst&quot;">​</a></h2><p>I dag lærer du praktiske mentale spilteknikker til at forbedre din petanque-præstation.</p><h3 id="hvad-du-vil-lære" tabindex="-1">Hvad du vil lære <a class="header-anchor" href="#hvad-du-vil-lære" aria-label="Permalink to &quot;Hvad du vil lære&quot;">​</a></h3><ul><li>Hvorfor mental træning er vigtig for elitespillere</li><li>Forskellen mellem &quot;teknisk tilstand&quot; og &quot;flowtilstand&quot;</li><li>Sådan genkender og håndterer du din indre kritiker</li><li>Enkle teknikker til trykhåndtering</li><li>En grundlæggende rutine før indtagelse</li></ul><hr><h2 id="zone-flowtilstanden" tabindex="-1">Zone-/flowtilstanden <a class="header-anchor" href="#zone-flowtilstanden" aria-label="Permalink to &quot;Zone-/flowtilstanden&quot;">​</a></h2><h3 id="hvad-er-flow" tabindex="-1">Hvad er flow? <a class="header-anchor" href="#hvad-er-flow" aria-label="Permalink to &quot;Hvad er flow?&quot;">​</a></h3><p>Flow er den magiske tilstand, hvor:</p><ul><li>Alt føles ubesværet</li><li>Tiden synes at gå langsommere</li><li>Du tænker ikke, du leger bare</li><li>Din teknik fungerer perfekt</li></ul><h3 id="to-sindstilstande" tabindex="-1">To sindstilstande <a class="header-anchor" href="#to-sindstilstande" aria-label="Permalink to &quot;To sindstilstande&quot;">​</a></h3><p><strong>Planlægningstilstand (Analytisk)</strong></p><ul><li>Analyse af terrænet</li><li>Valg af din strategi</li><li>Beslutning om skuddet</li><li>Vurdering af risici</li></ul><p><strong>Udførelsestilstand (Flow)</strong></p><ul><li>At stole på sin krop</li><li>Tænker ikke på teknik</li><li>Fokus i nuet</li><li>Automatisk udførelse</li></ul><h3 id="kontakten" tabindex="-1">Kontakten <a class="header-anchor" href="#kontakten" aria-label="Permalink to &quot;Kontakten&quot;">​</a></h3><p>Den vigtigste færdighed: <strong>skift fra planlægnings- til udførelsestilstand</strong></p><p><strong>Før optagelsen:</strong> Analyser, planlæg, beslut <strong>Under optagelsen:</strong> Tillid, flow, udførelse</p><hr><h2 id="den-indre-kritiker-vs-den-indre-coach" tabindex="-1">Den indre kritiker vs. den indre coach <a class="header-anchor" href="#den-indre-kritiker-vs-den-indre-coach" aria-label="Permalink to &quot;Den indre kritiker vs. den indre coach&quot;">​</a></h2><h3 id="din-indre-kritiker-siger" tabindex="-1">Din indre kritiker siger: <a class="header-anchor" href="#din-indre-kritiker-siger" aria-label="Permalink to &quot;Din indre kritiker siger:&quot;">​</a></h3><ul><li>&quot;Det var forfærdeligt!&quot;</li><li>&quot;Du laver altid fejl under pres&quot;</li><li>&quot;Alle ser dig fejle&quot;</li><li>&quot;Du er ikke god nok&quot;</li></ul><h3 id="din-indre-coach-siger" tabindex="-1">Din indre coach siger: <a class="header-anchor" href="#din-indre-coach-siger" aria-label="Permalink to &quot;Din indre coach siger:&quot;">​</a></h3><ul><li>&quot;Hvad kan jeg lære af dette?&quot;</li><li>&quot;Næste skud, en frisk start&quot;</li><li>&quot;Jeg har taget dette billede før&quot;</li><li>&quot;Stol på processen&quot;</li></ul><h3 id="reframing-øvelse" tabindex="-1">Reframing-øvelse <a class="header-anchor" href="#reframing-øvelse" aria-label="Permalink to &quot;Reframing-øvelse&quot;">​</a></h3><p>Når du bemærker din indre kritiker:</p><ol><li><strong>Pause</strong> - Anerkend den kritiske tanke</li><li><strong>Omformuler</strong> - Hvad ville din træner sige?</li><li><strong>Nulstil</strong> - Tag 3 indåndinger</li><li><strong>Refokusér</strong> - Næste billede</li></ol><hr><h2 id="praktiske-værktøjer" tabindex="-1">Praktiske værktøjer <a class="header-anchor" href="#praktiske-værktøjer" aria-label="Permalink to &quot;Praktiske værktøjer&quot;">​</a></h2><h3 id="_3-andedrætsnulstilling" tabindex="-1">3-åndedrætsnulstilling <a class="header-anchor" href="#_3-andedrætsnulstilling" aria-label="Permalink to &quot;3-åndedrætsnulstilling&quot;">​</a></h3><p>Brug dette efter fejl eller når du føler dig presset:</p><ol><li><strong>Åndedræt 1:</strong> Bemærk spændingen (hvor mærker du den?)</li><li><strong>Åndedræt 2:</strong> Slip spændingen (giv slip)</li><li><strong>Åndedræt 3:</strong> Fokuser på nuet (dette billede, dette øjeblik)</li></ol><h3 id="rutine-før-optagelse" tabindex="-1">Rutine før optagelse <a class="header-anchor" href="#rutine-før-optagelse" aria-label="Permalink to &quot;Rutine før optagelse&quot;">​</a></h3><p>Skab konsistens med en simpel rutine:</p><ol><li><strong>Visualiser</strong> - Se billedet for dig</li><li><strong>Træk vejret</strong> - En dyb indånding</li><li><strong>Anker</strong> - Rør din kugle, mærk vægten</li><li><strong>Udfør</strong> - Stol på og kast</li></ol><h3 id="protokol-for-fejlretning" tabindex="-1">Protokol for fejlretning <a class="header-anchor" href="#protokol-for-fejlretning" aria-label="Permalink to &quot;Protokol for fejlretning&quot;">​</a></h3><p>Efter et dårligt skud:</p><ol><li><strong>Anerkend</strong> - &quot;Det gik ikke som planlagt&quot;</li><li><strong>Udløsning</strong> - Fysisk nulstilling (ryst det af, gå)</li><li><strong>Refokusér</strong> - &quot;Næste skud er en ny mulighed&quot;</li><li><strong>Udfør</strong> - Stol på din rutine</li></ol><hr><h2 id="din-handlingsplan" tabindex="-1">Din handlingsplan <a class="header-anchor" href="#din-handlingsplan" aria-label="Permalink to &quot;Din handlingsplan&quot;">​</a></h2><h3 id="denne-uge" tabindex="-1">Denne uge <a class="header-anchor" href="#denne-uge" aria-label="Permalink to &quot;Denne uge&quot;">​</a></h3><p>Vælg ÉN teknik at øve:</p><ul><li>[ ] 3-Åndedrætsnulstilling efter hver fejl</li><li>[ ] Rutine før kast ved hvert kast</li><li>[] Omformuler én Indre Kritiker-tanke per session</li><li>[ ] Øv dig i at skifte fra planlægnings- til udførelsestilstand</li></ul><h3 id="spor-dine-fremskridt" tabindex="-1">Spor dine fremskridt <a class="header-anchor" href="#spor-dine-fremskridt" aria-label="Permalink to &quot;Spor dine fremskridt&quot;">​</a></h3><p>Meddelelse:</p><ul><li>Hvornår føler du dig mest i flow?</li><li>Hvad trigger din indre kritiker?</li><li>Hvilken teknik hjælper dig mest?</li><li>Hvordan ændrer din præstation sig?</li></ul><hr><h2 id="ressourcer-og-næste-skridt" tabindex="-1">Ressourcer og næste skridt <a class="header-anchor" href="#ressourcer-og-næste-skridt" aria-label="Permalink to &quot;Ressourcer og næste skridt&quot;">​</a></h2><h3 id="fortsæt-med-at-lære" tabindex="-1">Fortsæt med at lære <a class="header-anchor" href="#fortsæt-med-at-lære" aria-label="Permalink to &quot;Fortsæt med at lære&quot;">​</a></h3><ul><li><strong>Zonen</strong> - Dyk ned i flowtilstande</li><li><strong>Mental styrke</strong> - Avanceret preshåndtering</li><li><strong>Målskabelon</strong> - Strukturer din udvikling</li><li><strong>Skabelon til dagbog</strong> - Spor dine fremskridt</li></ul><h3 id="øv-dig-dagligt" tabindex="-1">Øv dig dagligt <a class="header-anchor" href="#øv-dig-dagligt" aria-label="Permalink to &quot;Øv dig dagligt&quot;">​</a></h3><ul><li>5 minutters bevidst vejrtrækning</li><li>Visualiser vellykkede optagelser</li><li>Øv din rutine før indtagelse</li><li>Omformuler negative tanker</li></ul><hr><h2 id="vigtige-konklusioner" tabindex="-1">Vigtige konklusioner <a class="header-anchor" href="#vigtige-konklusioner" aria-label="Permalink to &quot;Vigtige konklusioner&quot;">​</a></h2><ol><li><strong>Flowtilstand er tilgængelig</strong> - Du kan lære at indtaste den mere konsekvent</li><li><strong>Din indre stemme betyder noget</strong> - Coach dig selv, kritiser ikke</li><li><strong>Enkle værktøjer virker</strong> - 3 vejrtrækninger, en rutine, en nulstilling</li><li><strong>Øvelse er nøglen</strong> - Mentale færdigheder kræver træning ligesom tekniske færdigheder</li></ol><hr><p><strong>Husk:</strong> Mental træning handler ikke om positiv tænkning. Det handler om praktiske teknikker, der hjælper dig med at opnå din bedste præstation under pres.</p><hr><p><em>Besøg carreau.app for flere ressourcer</em><em>Pétanque Academy - Elite Player Development</em></p>',61)])])}]]);export{l as __pageData,n as default};
